const imageSanitize = "param($data)\n$ErrorActionPreference='Stop'\n$ProgressPreference='SilentlyContinue'\ntry {\n if($env:COMPUTERNAME -ine $data.name -or $env:USERNAME -ine $data.user){exit 1}\n $setup=Get-ItemProperty 'HKLM:\\SYSTEM\\Setup'\n if($setup.SystemSetupInProgress -ne 0 -or $setup.OOBEInProgress -ne 0){exit 1}\n function Assert-Ordinary([string]$Path){\n  if(Test-Path -LiteralPath $Path){if((Get-Item -Force -LiteralPath $Path).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'link'}}\n }\n $base='C:\\Windows\\AppSandbox'\n foreach($path in @('C:\\Windows',$base,'C:\\ProgramData','C:\\ProgramData\\ssh','C:\\actions-runner',\"$HOME\\.ssh\")){Assert-Ordinary $path}\n if(!(Test-Path -LiteralPath 'C:\\actions-runner\\bin\\Runner.Listener.exe' -PathType Leaf)){exit 1}\n foreach($path in @('C:\\ProgramData\\Bivouac','C:\\actions-runner\\.runner','C:\\actions-runner\\.credentials','C:\\actions-runner\\.credentials_rsaparams','C:\\actions-runner\\_work','C:\\actions-runner\\_diag')){if(Test-Path -LiteralPath $path){exit 1}}\n $probeBase='C:\\ProgramData\\BivouacHcsSpike'\n Assert-Ordinary $probeBase\n $entries=@(Get-ChildItem -Force -LiteralPath $probeBase)\n if($entries.Count -ne 2){exit 1}\n foreach($entry in $entries){if($entry.PSIsContainer -or $entry.Name -notin @('render.exe','render.json')){exit 1};Assert-Ordinary $entry.FullName}\n if((Get-FileHash -LiteralPath (Join-Path $probeBase 'render.exe') -Algorithm SHA256).Hash -ine $data.probe_sha256){exit 1}\n $reportPath=Join-Path $probeBase 'render.json'\n if((Get-Item -LiteralPath $reportPath).Length -gt 4096){exit 1}\n $observed=Get-Content -LiteralPath $reportPath -Raw|ConvertFrom-Json\n if(!$observed.hardware_d3d11 -or !$observed.presented -or !$observed.pixel_readback -or $observed.stage -ne 7 -or $observed.hresult -ne 0){exit 1}\n foreach($name in @('render.exe','render.json')){Remove-Item -Force -LiteralPath (Join-Path $probeBase $name)}\n Remove-Item -LiteralPath $probeBase\n $secretHelper=Join-Path $base 'hcs-spike-autologon.ps1'\n if((Get-FileHash -LiteralPath $secretHelper -Algorithm SHA256).Hash -ine $data.autologon_sha256){throw 'Autologon helper integrity differs'}\n . $secretHelper\n $random=New-Object byte[] 32\n $rng=[Security.Cryptography.RandomNumberGenerator]::Create()\n try{$rng.GetBytes($random)}finally{$rng.Dispose()}\n $password='Bv!'+[Convert]::ToBase64String($random)\n $secure=[Security.SecureString]::new()\n $characters=$password.ToCharArray()\n try{foreach($character in $characters){$secure.AppendChar($character)};$secure.MakeReadOnly()}finally{[Array]::Clear($characters,0,$characters.Length)}\n try{Set-LocalUser -Name $data.user -Password $secure}finally{$secure.Dispose()}\n $logon=[Microsoft.Win32.Registry]::LocalMachine.OpenSubKey('SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Winlogon',$true)\n try{\n  $logon.SetValue('AutoAdminLogon','1')\n  $logon.SetValue('DefaultUserName',$data.user)\n  $logon.SetValue('DefaultDomainName',$env:COMPUTERNAME)\n  if([SpikeAutoLogonSecret]::Store($password) -ne 0){throw 'Cannot protect clone autologon credential'}\n  $logon.DeleteValue('DefaultPassword',$false)\n  $logon.DeleteValue('AutoLogonCount',$false)\n }finally{$logon.Dispose();$password=$null;[Array]::Clear($random,0,$random.Length)}\n foreach($path in @('C:\\Windows\\Panther\\Unattend\\unattend.xml','C:\\Windows\\Panther\\Unattend\\specialize.ps1','C:\\Windows\\Panther\\unattend.xml','C:\\Windows\\System32\\Sysprep\\unattend.xml',\"$HOME\\.ssh\\authorized_keys\",'C:\\ProgramData\\ssh\\administrators_authorized_keys')){\n  $parent=Split-Path -Parent $path;Assert-Ordinary $parent;Assert-Ordinary $path\n  if(Test-Path -LiteralPath $path -PathType Leaf){Remove-Item -Force -LiteralPath $path}\n }\n $ssh='C:\\ProgramData\\ssh'\n $sshdConfig=Join-Path $ssh 'sshd_config';Assert-Ordinary $sshdConfig\n [IO.File]::WriteAllText($sshdConfig,\"ListenAddress 127.0.0.1`r`nPasswordAuthentication no`r`nKbdInteractiveAuthentication no`r`nPubkeyAuthentication yes`r`nStrictModes yes`r`nSubsystem sftp sftp-server.exe`r`nMatch Group administrators`r`n AuthorizedKeysFile __PROGRAMDATA__/ssh/administrators_authorized_keys`r`n\",[Text.UTF8Encoding]::new($false))\n $startup='\n$ErrorActionPreference=''Stop''\n$ProgressPreference=''SilentlyContinue''\n$service=Get-Service sshd\n$agent=Get-Service AppSandboxAgent\nif($service.StartType -ne ''Disabled'' -or $service.Status -ne ''Stopped'' -or $agent.StartType -ne ''Disabled'' -or $agent.Status -ne ''Stopped''){exit 1}\nforeach($name in @(''ssh_host_rsa_key'',''ssh_host_rsa_key.pub'',''ssh_host_ecdsa_key'',''ssh_host_ecdsa_key.pub'',''ssh_host_ed25519_key'',''ssh_host_ed25519_key.pub'')){\n $path=Join-Path ''C:\\ProgramData\\ssh'' $name\n if(Test-Path -LiteralPath $path){if((Get-Item -Force -LiteralPath $path).Attributes -band [IO.FileAttributes]::ReparsePoint){exit 1};Remove-Item -Force -LiteralPath $path}\n}\n$sshService=Get-CimInstance Win32_Service -Filter \"Name=''sshd''\"\n$binary=$sshService.PathName.Trim(''\"'')\nif($binary -notin @(''C:\\Program Files\\OpenSSH\\sshd.exe'',''C:\\Windows\\System32\\OpenSSH\\sshd.exe'')){exit 1}\n& (Join-Path (Split-Path -Parent $binary) ''ssh-keygen.exe'') @(''-A'') *> $null\nif($LASTEXITCODE){exit 1}\nforeach($name in @(''ssh_host_rsa_key'',''ssh_host_ecdsa_key'',''ssh_host_ed25519_key'')){if(!(Test-Path -LiteralPath (Join-Path ''C:\\ProgramData\\ssh'' $name) -PathType Leaf)){exit 1}}\nSet-Service sshd -StartupType Manual\nStart-Service sshd\nSet-Service AppSandboxAgent -StartupType Manual\nStart-Service AppSandboxAgent\n'\n $startupPath=Join-Path $base 'hcs-spike-startup.ps1';Assert-Ordinary $startupPath\n [IO.File]::WriteAllText($startupPath,$startup,[Text.UTF8Encoding]::new($false))\n $taskName='bivouac-hcs-ssh-hostkeys'\n if(Get-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue){exit 1}\n $principal=New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest\n $action=New-ScheduledTaskAction -Execute 'C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe' -Argument '-NoProfile -NonInteractive -ExecutionPolicy Bypass -File C:\\Windows\\AppSandbox\\hcs-spike-startup.ps1'\n $trigger=New-ScheduledTaskTrigger -AtStartup\n $settings=New-ScheduledTaskSettingsSet -ExecutionTimeLimit (New-TimeSpan -Minutes 2) -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries\n Register-ScheduledTask -TaskName $taskName -Principal $principal -Action $action -Trigger $trigger -Settings $settings|Out-Null\n # The upstream agent can re-enable sshd, so it must also stay stopped until\n # the boot task has generated server keys and started SSH.\n Set-Service AppSandboxAgent -StartupType Disabled\n Set-Service sshd -StartupType Disabled\n foreach($name in @('ssh_host_rsa_key','ssh_host_rsa_key.pub','ssh_host_ecdsa_key','ssh_host_ecdsa_key.pub','ssh_host_ed25519_key','ssh_host_ed25519_key.pub')){\n  $path=Join-Path $ssh $name;Assert-Ordinary $path\n  if(Test-Path -LiteralPath $path -PathType Leaf){Remove-Item -Force -LiteralPath $path}\n }\n $marker=Join-Path $base 'hcs-spike-prepared.json';Assert-Ordinary $marker\n if(Test-Path -LiteralPath $marker){exit 1}\n $metadata=[ordered]@{name=$data.name;user=$data.user;probe_sha256=$data.probe_sha256;validation_sha256=$data.validation_sha256;autologon_sha256=$data.autologon_sha256}\n [IO.File]::WriteAllText($marker,($metadata|ConvertTo-Json -Compress),[Text.UTF8Encoding]::new($false))\n # No further SSH process may run after removing host keys: OpenSSH can regenerate\n # missing keys when it spawns another server process. Shutdown uses this session.\n & 'C:\\Windows\\System32\\shutdown.exe' @('/s','/t','5','/d','p:0:0') *> $null\n if($LASTEXITCODE){exit 1}\n [Console]::Out.Write('sanitized-shutdown-scheduled');[Console]::Out.Flush()\n exit 0\n}catch{exit 1}\n"

const autologonSecret = "$ErrorActionPreference='Stop'\nAdd-Type -TypeDefinition @\"\nusing System;using System.Runtime.InteropServices;\npublic static class SpikeAutoLogonSecret {\n [StructLayout(LayoutKind.Sequential)] struct Unicode {public ushort Length,MaximumLength;public IntPtr Buffer;}\n [StructLayout(LayoutKind.Sequential)] struct Attributes {public uint Length;public IntPtr Root,ObjectName;public uint Flags;public IntPtr Descriptor,Quality;}\n [DllImport(\"advapi32.dll\"),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern uint LsaOpenPolicy(IntPtr system,ref Attributes attributes,uint access,out IntPtr policy);\n [DllImport(\"advapi32.dll\"),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern uint LsaStorePrivateData(IntPtr policy,ref Unicode name,ref Unicode value);\n [DllImport(\"advapi32.dll\"),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern uint LsaClose(IntPtr policy);\n public static uint Store(string password) {\n  if(password==null || password.Length==0 || password.Length>512)return 87;\n  var a=new Attributes();a.Length=(uint)Marshal.SizeOf(typeof(Attributes));IntPtr policy;\n  uint error=LsaOpenPolicy(IntPtr.Zero,ref a,0x20,out policy);if(error!=0)return error;\n  var name=new Unicode();var secret=new Unicode();\n  try {\n   string label=\"DefaultPassword\";name.Length=(ushort)(label.Length*2);name.MaximumLength=(ushort)(name.Length+2);name.Buffer=Marshal.StringToHGlobalUni(label);\n   secret.Length=(ushort)(password.Length*2);secret.MaximumLength=(ushort)(secret.Length+2);secret.Buffer=Marshal.StringToHGlobalUni(password);\n   return LsaStorePrivateData(policy,ref name,ref secret);\n  } finally {if(secret.Buffer!=IntPtr.Zero)Marshal.ZeroFreeGlobalAllocUnicode(secret.Buffer);if(name.Buffer!=IntPtr.Zero)Marshal.FreeHGlobal(name.Buffer);LsaClose(policy);}\n }\n}\n\"@\n"

const inspectDisk = "$ErrorActionPreference='Stop'\n$ProgressPreference='SilentlyContinue'\n$image=$null;$disk=$null;$partition=$null\ntry {\n $data=[Console]::In.ReadToEnd()|ConvertFrom-Json\n if($data.instance_id -cnotmatch '^[0-9a-f]{32}$'){exit 1}\n $child=Join-Path $data.root $data.instance_id\n $expectedDisk=Join-Path $child 'disk.vhdx'\n $marker=Get-Content -LiteralPath (Join-Path $child 'owner.json') -Raw|ConvertFrom-Json\n if($data.disk -cne $expectedDisk -or $marker.build_id -cne $data.instance_id -or $marker.workspace -cne $child){exit 1}\n foreach($path in @($child,$expectedDisk)){if((Get-Item -Force -LiteralPath $path).Attributes -band [IO.FileAttributes]::ReparsePoint){exit 1}}\n if((Get-DiskImage -ImagePath $expectedDisk).Attached){exit 1}\n Add-Type -TypeDefinition @\"\nusing System;using System.Text;using System.Runtime.InteropServices;\npublic static class FactoryInspection {\n [DllImport(\"offreg.dll\",CharSet=CharSet.Unicode),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] public static extern uint OROpenHive(string path,out IntPtr hive);\n [DllImport(\"offreg.dll\"),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] public static extern uint ORCloseHive(IntPtr hive);\n [DllImport(\"offreg.dll\",CharSet=CharSet.Unicode),DefaultDllImportSearchPaths(DllImportSearchPath.System32)] static extern uint ORGetValue(IntPtr hive,string key,string value,out uint type,byte[] data,ref uint size);\n public static uint Number(IntPtr hive,string key,string value) {uint type,size=4;byte[] data=new byte[4];uint error=ORGetValue(hive,key,value,out type,data,ref size);return error==0 && type==4 && size==4?BitConverter.ToUInt32(data,0):uint.MaxValue;}\n public static string State(IntPtr hive) {uint type,size=256;byte[] data=new byte[256];uint error=ORGetValue(hive,\"Microsoft\\\\Windows\\\\CurrentVersion\\\\Setup\\\\State\",\"ImageState\",out type,data,ref size);if(error!=0 || type!=1 || size>256 || size<2)return \"unknown\";return Encoding.Unicode.GetString(data,0,(int)size).TrimEnd('\\0')==\"IMAGE_STATE_GENERALIZE_RESEAL_TO_OOBE\"?\"generalized_to_oobe\":\"other\";}\n public static string Pointer(IntPtr hive) {uint type,size=0;uint error=ORGetValue(hive,\"Setup\",\"UnattendFile\",out type,null,ref size);if(error==2)return \"absent\";if(error!=0 || type!=1 || size>2)return \"present_or_unknown\";byte[] data=new byte[size];error=ORGetValue(hive,\"Setup\",\"UnattendFile\",out type,data,ref size);return error==0 && Array.TrueForAll(data,b=>b==0)?\"empty\":\"present_or_unknown\";}\n}\n\"@\n $mount=Join-Path $child 'inspect-mount'\n if(Test-Path -LiteralPath $mount){exit 1}\n New-Item -ItemType Directory -Path $mount|Out-Null\n $access=$mount+'\\'\n $facts=[ordered]@{system_hive_error=[uint32]::MaxValue;software_hive_error=[uint32]::MaxValue;system_setup_in_progress=[uint32]::MaxValue;oobe_in_progress=[uint32]::MaxValue;setup_phase=[uint32]::MaxValue;image_state_kind='unknown';unattend_pointer_kind='present_or_unknown';answer_directory_empty=$false;panther_answer_present=$false}\n try {\n  $image=Mount-DiskImage -ImagePath $expectedDisk -Access ReadOnly -NoDriveLetter -PassThru\n  $disk=$image|Get-Disk\n  $partition=Get-Partition -DiskNumber $disk.Number|Sort-Object Size -Descending|Select-Object -First 1\n  Add-PartitionAccessPath -DiskNumber $disk.Number -PartitionNumber $partition.PartitionNumber -AccessPath $access\n  foreach($relative in @('Windows','Windows\\Panther','Windows\\System32','Windows\\System32\\config','Windows\\System32\\config\\SYSTEM','Windows\\System32\\config\\SOFTWARE')){\n   $path=Join-Path $mount $relative\n   if(!(Test-Path -LiteralPath $path) -or ((Get-Item -Force -LiteralPath $path).Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'child Windows path'}\n  }\n  $system=Join-Path $mount 'Windows\\System32\\config\\SYSTEM'\n  $software=Join-Path $mount 'Windows\\System32\\config\\SOFTWARE'\n  if((Get-Item -LiteralPath $system).Length -gt 256MB -or (Get-Item -LiteralPath $software).Length -gt 256MB){throw 'hive bound'}\n  $hive=[IntPtr]::Zero\n  $facts.system_hive_error=[FactoryInspection]::OROpenHive($system,[ref]$hive)\n  if($facts.system_hive_error -eq 0){try{\n   $facts.system_setup_in_progress=[FactoryInspection]::Number($hive,'Setup','SystemSetupInProgress')\n   $facts.oobe_in_progress=[FactoryInspection]::Number($hive,'Setup','OOBEInProgress')\n   $facts.setup_phase=[FactoryInspection]::Number($hive,'Setup','SetupPhase')\n   $facts.unattend_pointer_kind=[FactoryInspection]::Pointer($hive)\n  }finally{[void][FactoryInspection]::ORCloseHive($hive)}}\n  $hive=[IntPtr]::Zero\n  $facts.software_hive_error=[FactoryInspection]::OROpenHive($software,[ref]$hive)\n  if($facts.software_hive_error -eq 0){try{$facts.image_state_kind=[FactoryInspection]::State($hive)}finally{[void][FactoryInspection]::ORCloseHive($hive)}}\n  $answer=Join-Path $mount 'Windows\\Panther\\Unattend'\n  if(!(Test-Path -LiteralPath $answer)){$facts.answer_directory_empty=$true}else{\n   $item=Get-Item -Force -LiteralPath $answer\n   $facts.answer_directory_empty=($item.PSIsContainer -and !($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -and !@(Get-ChildItem -Force -LiteralPath $answer|Select-Object -First 1).Count)\n  }\n  $facts.panther_answer_present=Test-Path -LiteralPath (Join-Path $mount 'Windows\\Panther\\unattend.xml')\n }finally{\n  if($image){try{if($partition){Remove-PartitionAccessPath -DiskNumber $disk.Number -PartitionNumber $partition.PartitionNumber -AccessPath $access}}finally{Dismount-DiskImage -ImagePath $expectedDisk}}\n }\n if((Get-DiskImage -ImagePath $expectedDisk).Attached){exit 1}\n Remove-Item -LiteralPath $mount\n [Console]::Out.Write(($facts|ConvertTo-Json -Compress));exit 0\n}catch{exit 1}\n"

const detachDisk = "$ErrorActionPreference='Stop'\n$ProgressPreference='SilentlyContinue'\ntry{\n $data=[Console]::In.ReadToEnd()|ConvertFrom-Json\n if($data.instance_id -cnotmatch '^[0-9a-f]{32}$'){exit 1}\n $child=Join-Path $data.root $data.instance_id\n $marker=Get-Content -LiteralPath (Join-Path $child 'owner.json') -Raw|ConvertFrom-Json\n $disk=Join-Path $child 'disk.vhdx'\n if($data.disk -cne $disk -or $marker.build_id -cne $data.instance_id -or $marker.workspace -cne $child){exit 1}\n foreach($path in @($child,$disk)){if((Get-Item -Force -LiteralPath $path).Attributes -band [IO.FileAttributes]::ReparsePoint){exit 1}}\n if((Get-DiskImage -ImagePath $disk).Attached){Dismount-DiskImage -ImagePath $disk}\n if((Get-DiskImage -ImagePath $disk).Attached){exit 1}\n exit 0\n}catch{exit 1}\n"

const runnerCheck = "function Assert-CleanRunner([string]$Runner) {\n if(!(Test-Path -LiteralPath $Runner)){return $false}\n $directory=Get-Item -Force -LiteralPath $Runner\n if(!$directory.PSIsContainer -or ($directory.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'runner directory'}\n foreach($entry in @(Get-ChildItem -Force -LiteralPath $Runner)){\n  if($entry.Name -eq '.runner' -or $entry.Name -like '.credentials*'){throw 'configured runner'}\n  if($entry.Name -in @('_work','_diag')){\n   if(!$entry.PSIsContainer -or ($entry.Attributes -band [IO.FileAttributes]::ReparsePoint) -or @(Get-ChildItem -Force -LiteralPath $entry.FullName | Select-Object -First 1).Count){throw 'runner residue'}\n  }\n }\n foreach($part in @('bin','bin\\Runner.Listener.exe','config.cmd','run.cmd')){\n  $path=Join-Path $Runner $part\n  if(!(Test-Path -LiteralPath $path)){throw 'runner incomplete'}\n  $item=Get-Item -Force -LiteralPath $path\n  if(($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -or ($part -eq 'bin' -and !$item.PSIsContainer) -or ($part -ne 'bin' -and ($item.PSIsContainer -or $item.Length -eq 0))){throw 'runner incomplete'}\n }\n return $true\n}\n"
